E = {}
for c, s in S.items():
    g, st, sl = c.split('_'); sex, look, items = LOOK[g + '_' + st]
    e = dict(s); e['sex'] = sex; e['look'] = look; e.setdefault('items', items)
    f = sex == 'f'
    e['story'] = e['story'].replace('{he}', 'she' if f else 'he').replace('{his}', 'her' if f else 'his').replace('{He}', 'She' if f else 'He')
    E[c] = e
json.dump(E, open('entries.json', 'w'), indent=1); print(len(E), 'entries')
